      <?php $youtubeResume=publishing_youtube_can_resume($job);$tiktokResume=publishing_tiktok_business_can_resume($job);if(in_array($job['status'],['failed','reconnect'],true)||($job['status']==='ambiguous'&&($youtubeResume||$tiktokResume))):?><details><summary><?=$tiktokResume?'Recheck the existing TikTok task':($youtubeResume?'Review and resume the existing YouTube upload':'Review a failed delivery')?></summary><form method="post" action="<?=url('/write/publishing/jobs/'.$job['id'].'/retry')?>"><?=csrf_field()?><label class="pub-choice"><input type="checkbox" name="reviewed_remote" value="1" required><span>I reviewed the existing provider record and resolved the reported problem. <?=$tiktokResume?'Read the status of the saved TikTok task; do not submit another video.':($youtubeResume?'Query and resume the saved YouTube session or video; do not create another upload.':'Resume this job, using its existing provider post when one exists.')?></span></label><button class="wbtn" type="submit">Resume reviewed job</button></form></details><?php endif;?>
      <?php $nativePending=$job['status']==='delivered'&&($youtubeResume||$tiktokResume);if(in_array($job['status'],['scheduled','assisted','failed','reconnect','ambiguous','reminder_queued','reminder_sent'],true)||$nativePending):?><details><summary>Cancel or close this record</summary><form method="post" action="<?=url('/write/publishing/jobs/'.$job['id'].'/cancel')?>"><?=csrf_field()?><?php if($job['remote_id']||$job['status']==='ambiguous'||$nativePending):?><label class="pub-choice"><input required type="checkbox" name="reviewed_remote" value="1"><span>I have checked and stopped any pending work in the provider. Closing this local record stops further upload work and status checks. It does not delete a video or cancel a remote post already accepted.</span></label><?php endif;?><button class="pub-muted-button" type="submit">Cancel local job</button></form></details><?php endif;?>
    </article><?php endforeach;?>
  </div></section>
  <?php if($events):?><details class="pub-details"><summary>Publication history</summary><div><ol class="pub-timeline"><?php foreach($events as $event):?><li><strong><?=e(ucfirst(str_replace('_',' ',$event['event_type'])))?></strong><p><?=e($event['note'])?></p><time><?=e(format_date($event['created_at']))?></time></li><?php endforeach;?></ol></div></details><?php endif;?>
  <?php endif;?>
</main>
<script src="<?=asset('js/publishing-automation.js')?>" defer></script>
